-- Cosmetics (FDA): five combined questions split (new CM10-CM16).
update public.hub_chk_points set q='Is the cosmetics licence (COS-8) valid?', why='Making cosmetics on a lapsed licence is manufacture without licence.', law='Cosmetics Rules 2020 r.23–26', evidence='Licence + fee receipt', updated_at=now() where code='CM01';
update public.hub_chk_points set q='Do labels show the product name, maker''s address and net content?', why='Label errors are the top reason cosmetics fail on Amazon and in inspections.', law='Cosmetics Rules 2020 r.34', evidence='Approved label artwork', updated_at=now() where code='CM03';
update public.hub_chk_points set q='Is a batch record kept for every batch?', why='Required under cosmetics GMP and asked for at every inspection.', law='Cosmetics Rules 2020, Seventh Schedule', evidence='Sample batch record', updated_at=now() where code='CM05';
update public.hub_chk_points set q='Are finished products tested to the BIS standard (including heavy metals and microbial limits)?', why='A failed market sample leads to prosecution.', law='Cosmetics Rules 2020 r.26, Ninth Schedule', evidence='Test reports', updated_at=now() where code='CM07';
update public.hub_chk_points set q='Is every new product within the licensed categories?', why='Keeps the licence and the actual product range matched.', law='Cosmetics Rules 2020 r.23', evidence='Approved product list', updated_at=now() where code='CM08';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CM10','Cosmetics (FDA)','Is the cosmetics licence displayed?','Inspectors expect the licence on display at the premises.','Cosmetics Rules 2020 r.23–26','cos_mfg',array['fda']::text[],'M','Photo of displayed licence',9750,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CM11','Cosmetics (FDA)','Does the licence cover every category we make?','Making a category not on the licence is manufacture without licence.','Cosmetics Rules 2020 r.23–26','cos_mfg',array['fda']::text[],'H','Licence categories against product list',9751,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CM12','Cosmetics (FDA)','Do labels show the batch number, Mfg date and use-before date?','Label errors are the top reason cosmetics fail on Amazon and in inspections.','Cosmetics Rules 2020 r.34','cos_mfg',array['fda']::text[],'H','Approved label artwork',9752,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CM13','Cosmetics (FDA)','Do labels show the ingredients and licence number?','Label errors are the top reason cosmetics fail on Amazon and in inspections.','Cosmetics Rules 2020 r.34','cos_mfg',array['fda']::text[],'H','Approved label artwork',9753,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CM14','Cosmetics (FDA)','Are raw materials tested before use?','Required under cosmetics GMP and asked for at every inspection.','Cosmetics Rules 2020, Seventh Schedule','cos_mfg',array['fda']::text[],'H','Raw material test reports',9754,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CM15','Cosmetics (FDA)','Are finished-product test records kept for 3 years?','A failed market sample leads to prosecution.','Cosmetics Rules 2020 r.26, Ninth Schedule','cos_mfg',array['fda']::text[],'M','Record room list',9755,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CM16','Cosmetics (FDA)','Is the product list given to FDA where required?','Keeps the licence and the actual product range matched.','Cosmetics Rules 2020 r.23','cos_mfg',array['fda']::text[],'M','Product list intimation',9756,true,null) on conflict (code) do nothing;
