-- Existing answers (Velite Healthcare): 'Yes' that covered both halves is copied to the new question; CM05 'No' (note: RM Testing) is flagged for re-check.
insert into public.hub_chk_answers(firm_id, code, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at)
  select firm_id, t.c, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at from public.hub_chk_answers, (values ('CM01','CM10'),('CM01','CM11'),('CM03','CM12'),('CM03','CM13'),('CM07','CM15'),('CM08','CM16')) as t(f,c) where code=t.f and firm_id='VH' and answer in ('yes','na') on conflict do nothing;
update public.hub_chk_answers set stale=true, stale_reason='question was split in two, please confirm which part this No is about (note says RM Testing)' where code='CM05' and firm_id='VH';
